500	    /**
501	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
502	     * bytes of {@code value}.
503	     */
504	    private static String sha256HexUpper(String value, int length) {
505	        try {
506	            byte[] digest = MessageDigest.getInstance("SHA-256")
507	                .digest(value.getBytes(StandardCharsets.UTF_8));
508	            StringBuilder sb = new StringBuilder(digest.length * 2);
509	            for (byte b : digest) {
510	                sb.append(String.format("%02X", b));
511	            }
512	            return sb.substring(0, length);
513	        }
514	        catch (NoSuchAlgorithmException e) {
515	            throw new IllegalStateException(e);
516	        }
517	    }
